/// Permission bits applied to directories created as parents.
#[derive(Clone, Debug)]
pub struct ModePlan {
    /// Mode assigned to parent directories created with `-p`.
    pub parent_mode: u32,
    /// Reporting details for created directories.
    pub report: CreationReport,
}

/// Layout of a directory that should be created.
#[derive(Clone, Debug)]
pub struct DirectoryLayout {
    /// Path of the directory to create.
    pub target: PathBuf,
    /// Whether this path is an intermediate parent.
    pub is_parent: bool,
    /// Mode and reporting plan for the directory.
    pub mode_plan: ModePlan,
}

impl DirectoryLayout {
    /// Build a layout describing a directory creation request.
    pub fn for_creation(
        target: PathBuf,
        is_parent: bool,
        parent_mode: u32,
        verbose: bool,
    ) -> Self {
        Self {
            target,
            is_parent,
            mode_plan: ModePlan {
                parent_mode,
                report: CreationReport::for_directory_creation(verbose),
            },
        }
    }

    /// Derive a layout for an ancestor that must be created first.
    pub fn for_parent(&self, parent: &Path) -> Self {
        Self {
            target: parent.to_path_buf(),
            is_parent: true,
            mode_plan: self.mode_plan.clone(),
        }
    }
}

/// For some programs like install or mkdir, dir/. can be provided
/// Special case to match GNU's behavior:
/// install -d foo/. should work and just create foo/
/// std::fs::create_dir("foo/."); fails in pure Rust
pub fn dir_strip_dot_for_creation(path: &Path) -> PathBuf {
    if path.to_string_lossy().ends_with("/.") {
        // Do a simple dance to strip the "/."
        Path::new(&path).components().collect::<PathBuf>()
    } else {
        path.to_path_buf()
    }
}

/// Checks if `p1` and `p2` are the same file.
/// If error happens when trying to get files' metadata, returns false
pub fn paths_refer_to_same_file<P: AsRef<Path>>(p1: P, p2: P, dereference: bool) -> bool {
    infos_refer_to_same_file(
        FileInformation::from_path(p1, dereference),
        FileInformation::from_path(p2, dereference),
    )
}

/// Checks if `p1` and `p2` are the same file information.
/// If error happens when trying to get files' metadata, returns false
pub fn infos_refer_to_same_file(
    info1: IOResult<FileInformation>,
    info2: IOResult<FileInformation>,
) -> bool {
    if let Ok(info1) = info1 {
        if let Ok(info2) = info2 {
            return info1 == info2;
        }
    }
    false
}

