/// Owns mkdir's recursive-creation switch and performs directory creation.
struct MkdirEngine {
    /// Whether missing parent directories should be created.
    recursive: bool,
}

#[cfg(any(unix, target_os = "redox"))]
fn chmod(path: &Path, mode: u32) -> UResult<()> {
    use std::fs::{set_permissions, Permissions};
    use std::os::unix::fs::PermissionsExt;

    let mode = Permissions::from_mode(mode);

    set_permissions(path, mode)
        .map_err_context(|| format!("cannot set permissions {}", path.quote()))
}

#[cfg(windows)]
fn chmod(_path: &Path, _mode: u32) -> UResult<()> {
    // chmod on Windows only sets the readonly flag, which isn't even honored on directories
    Ok(())
}

impl MkdirEngine {
    // `is_parent` argument is not used on windows
    #[allow(unused_variables)]
    fn create_dir(&self, layout: &DirectoryLayout) -> UResult<bool> {
        let path = layout.target.as_path();
        let is_parent = layout.is_parent;
        let mode_plan = &layout.mode_plan;
        let parent_mode = mode_plan.parent_mode;
        let report = &mode_plan.report;
        let verbose = report.verbose;
        let status = &report.status;
        let exists_code = status.exists_code;
        let existing = &status.existing;
        let accept_directory = existing.accept_directory;
        let components = &existing.components;
        let allow_empty_path = components.allow_empty_path;
        let ignore_missing_root = components.ignore_missing_root;

        if path.exists() && !self.recursive {
            return Err(USimpleError::new(
                exists_code,
                format!("{}: File exists", path.display()),
            ));
        }
        if allow_empty_path && path == Path::new("") {
            return Ok(());
        }

        if self.recursive {
            match path.parent() {
                Some(p) => {
                    self.create_dir(&layout.for_parent(p))?;
                }
                None => {
                    if !ignore_missing_root {
                        USimpleError::new(exists_code, "failed to create whole tree");
                    }
                }
            }
        }
        match std::fs::create_dir(path) {
            Ok(()) => {
                if verbose {
                    println!(
                        "{}: created directory {}",
                        uucore::util_name(),
                        path.quote()
                    );
                }
                #[cfg(not(windows))]
                if is_parent {
                    // directories created by -p have permission bits set to '=rwx,u+wx',
                    // which is umask modified by 'u+wx'
                    chmod(path, parent_mode)?;
                }
                Ok(())
            }
            Err(_) if accept_directory && path.is_dir() => Ok(()),
            Err(e) => Err(e.into()),
        }
    }
}

